function main(): void {
  const j: any = JSON.parse('[3,1,2]');
  const alias = j;
  console.log(j.push(9), alias.length, alias[3]);
  console.log(j.pop(), j.shift(), j.unshift(0), alias.join(','));
  j.sort();
  console.log(alias.join(','), j.map((x: number) => x * 2).join(','), j.filter((x: number) => x > 1).length);
  console.log(j.reduce((s: number, x: number) => s + x, 0), j.some((x: number) => x > 2), j.slice(1).join(','));
  const k: any = JSON.parse('{"list":[1,2]}');
  k.list.push(3);
  console.log(k.list.length, JSON.stringify(k));
}
